SELECT MONTH(launch_date) AS launch_month, CASE WHEN stock_qty >= 375 THEN 'high' WHEN stock_qty >= 72 THEN 'mid' ELSE 'low' END AS stock_qty_bucket, SORT_ARRAY(COLLECT_SET(category)) AS category_list, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(category))) AS category_values FROM products WHERE supplier_id IS NOT NULL GROUP BY CUBE(MONTH(launch_date), CASE WHEN stock_qty >= 375 THEN 'high' WHEN stock_qty >= 72 THEN 'mid' ELSE 'low' END) ORDER BY 1, category_values DESC
